contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // params: initial deposit to ensure some balance, MinSum to set threshold, requested collect amount
    function run(uint initialDeposit, uint MinSum, uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (initialDeposit)); require(initialDeposit <= 1000000000000000000000000000000);
        require(address(this).balance >= initialDeposit, "need funds to deposit");

        // initialize C (must set log and min sum before Initialized)
        c.SetMinSum(MinSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(c)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // deposit funds into C from this contract
        c.Deposit{value: initialDeposit}(); if (__ESBMC_reverted()) return;

        // snapshot before values
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // attempt Collect and record whether it reverted
        bool success;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = true;
        }

        // snapshot after values
        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // General invariant: Collect never increases the recorded balance for the caller.
        // If success then recorded balance decreased by at most _am (i.e., beforeBal >= afterBal && beforeBal - afterBal <= _am).
        // If failure then recorded balance unchanged.
        assert(
            (!success && afterBal == beforeBal)
            || (success && beforeBal >= afterBal && (beforeBal - afterBal) <= _am)
        );
    }

    receive() external payable {}
}

