// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 initialDeposit, uint256 MinSum, uint256 _am) internal {
        initialDeposit = bound(initialDeposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= initialDeposit);
        try c.SetMinSum(MinSum) {} catch { return; }
        try c.SetLogFile(address(c)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: initialDeposit}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        bool success;
        try c.Collect(_am) {
            success = true;
        } catch {
            success = false;
        }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue((!success && afterBal == beforeBal)
            || (success && beforeBal >= afterBal && (beforeBal - afterBal) <= _am));
    }

    function testFuzz_run(uint256 initialDeposit, uint256 MinSum, uint256 _am) public {
        _run(initialDeposit, MinSum, _am);
    }

    receive() external payable {}
}
